        <p class="lc-meta mt-4 text-[length:var(--text-lg)]">Medellín, Colombia, 1973</p>
        <div class="mt-5 flex flex-wrap gap-3">
          <a class="lc-btn" href="#obras">Ver la obra disponible</a>
          <a class="lc-btn lc-btn--ghost" href="/obras/?artista=camilo-restrepo">Ver todo en el catálogo</a>
