            <button type="button" class="lc-link mt-3" data-inquire="Drawing #1 — Camilo Restrepo">Consultar <span class="lc-arrow" aria-hidden="true">→</span></button>
          </li>
          <li class="lc-card w-[min(78vw,20rem)]">
            <a href="/preview/1090" class="block">
